38	@Riverpod(keepAlive: true)
39	class MapController extends _$MapController {
40	  LocationIndicator? _locationIndicator;
41	  GeoCoordinates? _lastLocation;
42	
43	  // Keyed by checkpointId for O(1) diffing.
44	  final Map<String, MapMarker> _markerById = {};
45	  bool _checkpointsVisible = true;
