64	  void setController(
65	    HereMapController controller,
66	    void Function(String) onCheckpointTap,
67	  ) {
68	    state = controller;
69	    _setupLocationIndicator(controller);
70	    _setupGestureListeners(controller, onCheckpointTap);
71	    unawaited(_loadAndApplyPreferences());
