74	  Future<void> _loadAndApplyPreferences() async {
75	    final prefs = ref.read(mapPreferencesRepositoryProvider);
76	    final schemeName = await prefs.getMapScheme();
77	    final trafficOn = await prefs.isTrafficEnabled();
78	    final transitOn = await prefs.isPublicTransitEnabled();
79	    final camerasOn = await prefs.isSafetyCamerasEnabled();
80	    final lightsOn = await prefs.isTrafficLightsEnabled();
81	    final zonesOn = await prefs.isCongestionZonesEnabled();
82	    final exitsOn = await prefs.isRoadExitLabelsEnabled();
83	
84	    final scheme = MapScheme.values.firstWhere(
85	      (s) => s.name == schemeName,
86	      orElse: () => MapScheme.normalDay,
87	    );
88	
89	    ref.read(isTrafficEnabledProvider.notifier).state = trafficOn;
90	    ref.read(isPublicTransitEnabledProvider.notifier).state = transitOn;
91	    ref.read(isSafetyCamerasEnabledProvider.notifier).state = camerasOn;
92	    ref.read(isTrafficLightsEnabledProvider.notifier).state = lightsOn;
93	    ref.read(isCongestionZonesEnabledProvider.notifier).state = zonesOn;
94	    ref.read(isRoadExitLabelsEnabledProvider.notifier).state = exitsOn;
95	
96	    if (state != null) {
97	      setMapScheme(scheme, refocus: true);
98	    }
99	  }
