101	  void _setupGestureListeners(
102	    HereMapController controller,
103	    void Function(String) onCheckpointTap,
104	  ) {
105	    controller.gestures.tapListener = TapListener((Point2D point) {
106	      final current = state;
107	      if (current == null) return;
108	
109	      current.pick(
110	        MapSceneMapPickFilter([MapSceneMapPickFilterContentType.mapItems]),
111	        Rectangle2D(point, Size2D(40, 40)),
112	        (MapPickResult? result) {
113	          final marker = result?.mapItems?.markers.firstOrNull;
114	          if (marker == null) return;
115	          final id = marker.metadata?.getString('checkpointId');
116	          if (id != null) onCheckpointTap(id);
117	        },
118	      );
119	    });
120	  }
