122	  void _setupLocationIndicator(HereMapController controller) {
123	    _locationIndicator = LocationIndicator.withMapView(controller)
124	      ..locationIndicatorStyle = LocationIndicatorIndicatorStyle.pedestrian
125	      ..enable(controller);
