128	  // Called once from _onMapCreated when the map is already centered on the
129	  // user's position. Sets _lastLocation so updateLocation won't trigger the
130	  // fly animation on the next GPS update.
131	  void setInitialLocation(GeoCoordinates coordinates) {
132	    _lastLocation = coordinates;
133	    _locationIndicator?.updateLocation(Location.withCoordinates(coordinates));
134	    _prefetchAroundLocation(coordinates);
135	  }
136	
137	  void updateLocation(GeoCoordinates coordinates) {
138	    final isFirstLocation = _lastLocation == null;
139	    _lastLocation = coordinates;
140	    _locationIndicator?.updateLocation(Location.withCoordinates(coordinates));
141	
142	    if (isFirstLocation) {
143	      focusOnUserLocation();
144	      _prefetchAroundLocation(coordinates);
145	    }
146	  }
