148	  void _prefetchAroundLocation(GeoCoordinates coords) {
149	    final engine = SDKNativeEngine.sharedInstance;
150	    if (engine == null || _hasPrefetched) return;
151	    _hasPrefetched = true;
152	
153	    _prefetcher ??= PolygonPrefetcher(engine);
154	    final polygon = GeoPolygon.withGeoCircle(GeoCircle(coords, 3000));
155	    _prefetcher!.prefetch(
156	      polygon,
157	      PrefetchStatusListener(
158	        (_) {},
159	        (error) {
160	          if (error != null) {
161	            AppLogger.error(
162	              'Tile prefetch failed',
163	              error: error,
164	              stackTrace: StackTrace.current,
165	            );
166	          }
167	        },
168	      ),
169	    );
170	  }
