180	  void _animateTo(GeoCoordinates? coords) {
181	    if (coords == null || state == null) return;
182	    final animation = MapCameraAnimationFactory.flyToWithZoom(
183	      GeoCoordinatesUpdate(coords.latitude, coords.longitude),
184	      MapMeasure(MapMeasureKind.distanceInMeters, 1000),
185	      0,
186	      const Duration(milliseconds: 800),
187	    );
188	    state!.camera.startAnimation(animation);
189	  }
