191	  void resetOrientationToNorth() {
192	    final controller = state;
193	    if (controller == null) return;
194	
195	    final cameraState = controller.camera.state;
196	    final animation = MapCameraAnimationFactory.flyToWithOrientationAndZoom(
197	      GeoCoordinatesUpdate(
198	        cameraState.targetCoordinates.latitude,
199	        cameraState.targetCoordinates.longitude,
200	      ),
201	      GeoOrientationUpdate(0, cameraState.orientationAtTarget.tilt),
202	      MapMeasure(
203	        MapMeasureKind.distanceInMeters,
204	        cameraState.distanceToTargetInMeters,
205	      ),
206	      0,
207	      const Duration(milliseconds: 600),
208	    );
209	    controller.camera.startAnimation(animation);
210	
211	    ref.read(mapBearingProvider.notifier).state = 0.0;
212	  }
