214	  // Builds a new MapMarker for a checkpoint, embedding its status in metadata
215	  // so the diff logic can detect when the icon needs refreshing.
216	  MapMarker _buildMarker(
217	    Checkpoint checkpoint,
218	    Map<ContributionStatusEnum, MapImage> icons,
219	  ) {
220	    final status = checkpoint.contributions.isNotEmpty
221	        ? checkpoint.contributions.first.status
222	        : ContributionStatusEnum.UNKNOWN;
223	    final icon = icons[status] ?? icons[ContributionStatusEnum.UNKNOWN]!;
224	    return MapMarker(
225	      GeoCoordinates(
226	        checkpoint.latitude.toDouble(),
227	        checkpoint.longitude.toDouble(),
228	      ),
229	      icon,
230	    )..metadata = (Metadata()
231	      ..setString('checkpointId', checkpoint.id)
232	      ..setString('status', status.name));
233	  }
234	
235	  ContributionStatusEnum _statusFor(Checkpoint checkpoint) =>
236	      checkpoint.contributions.isNotEmpty
237	          ? checkpoint.contributions.first.status
238	          : ContributionStatusEnum.UNKNOWN;
