240	  // ── Checkpoint visibility (hidden during active drive) ────────────────────
241	
242	  void hideCheckpoints() {
243	    if (!_checkpointsVisible) return;
244	    _checkpointsVisible = false;
245	    final controller = state;
246	    if (controller == null || _markerById.isEmpty) return;
247	    controller.mapScene.removeMapMarkers(_markerById.values.toList());
248	  }
