250	  void showCheckpoints() {
251	    if (_checkpointsVisible) return;
252	    _checkpointsVisible = true;
253	    final controller = state;
254	    if (controller == null || _markerById.isEmpty) return;
255	    controller.mapScene.addMapMarkers(_markerById.values.toList());
256	  }
