258	  // Diffs the current marker set against the incoming checkpoints:
259	  // only removes stale markers and adds new/changed ones, in batches.
260	  void updateCheckpoints(
261	    List<Checkpoint> checkpoints,
262	    Map<ContributionStatusEnum, MapImage> icons,
263	  ) {
264	    final controller = state;
265	    if (controller == null) return;
266	
267	    final desired = {for (final c in checkpoints) c.id: c};
268	
269	    // Remove markers no longer needed.
270	    final staleIds = _markerById.keys
271	        .where((id) => !desired.containsKey(id))
272	        .toList();
273	    if (staleIds.isNotEmpty) {
274	      if (_checkpointsVisible) {
275	        controller.mapScene.removeMapMarkers(
276	          staleIds.map((id) => _markerById[id]!).toList(),
277	        );
278	      }
279	      staleIds.forEach(_markerById.remove);
280	    }
281	
282	    // Add new markers and refresh any whose status changed.
283	    final toAdd = <MapMarker>[];
284	    for (final checkpoint in checkpoints) {
285	      final existing = _markerById[checkpoint.id];
286	      if (existing != null) {
287	        final currentStatus = existing.metadata?.getString('status');
288	        if (currentStatus == _statusFor(checkpoint).name) continue;
289	        // Status changed — replace.
290	        if (_checkpointsVisible) {
291	          controller.mapScene.removeMapMarker(existing);
292	        }
293	        _markerById.remove(checkpoint.id);
294	      }
295	      final marker = _buildMarker(checkpoint, icons);
296	      toAdd.add(marker);
297	      _markerById[checkpoint.id] = marker;
298	    }
299	    if (toAdd.isNotEmpty && _checkpointsVisible) {
300	      controller.mapScene.addMapMarkers(toAdd);
301	    }
302	  }
