304	  void setMapScheme(MapScheme scheme, {bool refocus = false}) {
305	    ref.read(currentMapSchemeProvider.notifier).state = scheme;
306	
307	    unawaited(
308	      ref.read(mapPreferencesRepositoryProvider).setMapScheme(scheme.name),
309	    );
310	
311	    final coordinates = refocus ? _lastLocation : null;
312	
313	    final options = MapSceneLoadOptionsBuilder().withMapScheme(scheme).build();
314	    state?.mapScene.loadScene(options, (MapError? error) {
315	      if (error != null) {
316	        AppLogger.error(
317	          'Map scene load failed',
318	          error: error,
319	          stackTrace: StackTrace.current,
320	        );
321	        return;
322	      }
323	      _reapplyFeatures();
324	      if (coordinates != null) {
325	        _animateTo(coordinates);
326	      }
327	    });
328	  }
