330	  void _reapplyFeatures() {
331	    final controller = state;
332	    if (controller == null) return;
333	
334	    final scheme = ref.read(currentMapSchemeProvider);
335	    if (scheme == MapScheme.satellite) return;
336	
337	    final trafficOn = ref.read(isTrafficEnabledProvider);
338	    final transitOn = ref.read(isPublicTransitEnabledProvider);
339	    final camerasOn = ref.read(isSafetyCamerasEnabledProvider);
340	    final lightsOn = ref.read(isTrafficLightsEnabledProvider);
341	    final zonesOn = ref.read(isCongestionZonesEnabledProvider);
342	    final exitsOn = ref.read(isRoadExitLabelsEnabledProvider);
343	
344	    if (trafficOn) {
345	      controller.mapScene.enableFeatures({
346	        MapFeatures.trafficFlow: MapFeatureModes.trafficFlowWithFreeFlow,
347	        MapFeatures.trafficIncidents: MapFeatureModes.trafficIncidentsAll,
348	      });
349	    }
350	    if (transitOn) {
351	      controller.mapScene.enableFeatures({
352	        MapFeatures.publicTransit: MapFeatureModes.publicTransitAll,
353	      });
354	    }
355	    if (camerasOn) {
356	      controller.mapScene.enableFeatures({
357	        MapFeatures.safetyCameras: MapFeatureModes.safetyCamerasAll,
358	      });
359	    }
360	    if (lightsOn) {
361	      controller.mapScene.enableFeatures({
362	        MapFeatures.trafficLights: MapFeatureModes.trafficLightsAll,
363	      });
364	    }
365	    if (zonesOn) {
366	      controller.mapScene.enableFeatures({
367	        MapFeatures.congestionZones: MapFeatureModes.congestionZonesAll,
368	      });
369	    }
370	    if (exitsOn) {
371	      controller.mapScene.enableFeatures({
372	        MapFeatures.roadExitLabels: MapFeatureModes.roadExitLabelsAll,
373	      });
374	    }
375	  }
