519	  // ── Route preview ──────────────────────────────────────────────────────────
520	
521	  Future<void> showRoute(Route route) async {
522	    final controller = state;
523	    if (controller == null) return;
524	
525	    clearRoute();
526	
527	    // Polyline: 24px blue with 6px white outline (physical pixels;
528	    // ~8dp on a 3× screen — same weight as Google Maps route line).
529	    final lineWidth = MapMeasureDependentRenderSize.withSingleSize(
530	      RenderSizeUnit.pixels,
531	      24,
532	    );
533	    final outlineWidth = MapMeasureDependentRenderSize.withSingleSize(
534	      RenderSizeUnit.pixels,
535	      6,
536	    );
537	    final rep = MapPolylineSolidRepresentation.withOutline(
538	      lineWidth,
539	      const ui.Color(0xFF3E5BFF),
540	      outlineWidth,
541	      Colors.white,
542	      LineCap.round,
543	    );
544	    final polyline = MapPolyline.withRepresentation(route.geometry, rep);
545	    controller.mapScene.addMapPolyline(polyline);
546	    _routePolyline = polyline;
547	
548	    // Origin (blue) + dest (red) circle markers.
549	    final verts = route.geometry.vertices;
550	    if (verts.isNotEmpty) {
551	      final originImg = await _circlePng(const ui.Color(0xFF3E5BFF), 20);
552	      final destImg   = await _circlePng(const ui.Color(0xFFE63946), 24);
553	
554	      // State may have been cleared while we awaited the PNG renders.
555	      if (state == null) return;
556	
557	      final originMarker = MapMarker(verts.first, originImg);
558	      final destMarker   = MapMarker(verts.last,  destImg);
559	      controller.mapScene.addMapMarker(originMarker);
560	      controller.mapScene.addMapMarker(destMarker);
561	      _routeOriginMarker = originMarker;
562	      _routeDestMarker   = destMarker;
563	    }
564	
565	    // Fit camera to the route bounding box (north-up, no tilt).
566	    controller.camera.applyUpdate(
567	      MapCameraUpdateFactory.lookAtArea(route.boundingBox),
568	    );
569	  }
570	
571	  void clearRoute() {
572	    final controller = state;
573	    if (controller == null) return;
574	
575	    if (_routePolyline != null) {
576	      controller.mapScene.removeMapPolyline(_routePolyline!);
577	      _routePolyline = null;
578	    }
579	    if (_routeOriginMarker != null) {
580	      controller.mapScene.removeMapMarker(_routeOriginMarker!);
581	      _routeOriginMarker = null;
582	    }
583	    if (_routeDestMarker != null) {
584	      controller.mapScene.removeMapMarker(_routeDestMarker!);
585	      _routeDestMarker = null;
586	    }
587	  }
