589	  // Renders a filled circle with a white halo as a PNG MapImage.
590	  Future<MapImage> _circlePng(ui.Color color, double size) async {
591	    final recorder = ui.PictureRecorder();
592	    final canvas   = ui.Canvas(recorder);
593	    final half     = size / 2;
594	    canvas
595	      ..drawCircle(
596	        ui.Offset(half, half),
597	        half,
598	        ui.Paint()..color = const ui.Color(0xFFFFFFFF),
599	      )
600	      ..drawCircle(
601	        ui.Offset(half, half),
602	        half - 2,
603	        ui.Paint()..color = color,
604	      );
605	    final picture = recorder.endRecording();
606	    final img     = await picture.toImage(size.toInt(), size.toInt());
607	    final bd      = await img.toByteData(format: ui.ImageByteFormat.png);
608	    return MapImage.withPixelDataAndImageFormat(
609	      bd!.buffer.asUint8List(),
610	      ImageFormat.png,
611	    );
612	  }
