20	@Riverpod(keepAlive: true)
21	class NavStateNotifier extends _$NavStateNotifier {
22	  VisualNavigator? _navigator;
23	  RoutingEngine? _routingEngine;
24	  Timer? _recenterTimer;
25	  StreamSubscription<Position>? _locationSub;
26	
27	  @override
28	  NavigationPhase build() {
29	    _routingEngine = RoutingEngine();
30	    ref.onDispose(_teardown);
31	    return const Idle();
32	  }
33	
34	  // ── Route calculation ─────────────────────────────────────────────────────
35	
36	  void calculateRoute({
37	    required GeoCoordinates origin,
38	    required GeoCoordinates dest,
39	  }) {
40	    final engine = _routingEngine;
41	    if (engine == null) return;
42	
43	    final waypoints = [Waypoint(origin), Waypoint(dest)];
44	    final options = buildUkCarOptions();
45	
46	    engine.calculateRouteWithRoutingOptions(
47	      waypoints,
48	      options,
49	      (RoutingError? err, List<Route>? routes) {
50	        ref.read(navSearchNotifierProvider.notifier).unlockRouting();
51	        if (err != null || routes == null || routes.isEmpty) {
52	          ref
53	              .read(navSearchNotifierProvider.notifier)
54	              .setError(NavStrings.routeError);
55	          return;
56	        }
57	        final route = routes.first;
58	        state = TripOverview(route: route);
59	        ref.read(sheetStateNotifierProvider.notifier).showTripOverview();
60	        unawaited(ref.read(mapControllerProvider.notifier).showRoute(route));
61	      },
62	    );
63	  }
64	
65	  // ── Drive lifecycle ───────────────────────────────────────────────────────
66	
67	  void startDrive(Route route) {
68	    final mapController = ref.read(mapControllerProvider);
69	    if (mapController == null) return;
70	
71	    _teardown();
72	
73	    final nav = VisualNavigator();
74	    _navigator = nav;
75	
76	    nav.startRendering(mapController);
77	    applyUkUnitsToNavigator(nav);
78	
79	    nav.routeDeviationListener = _DeviationAdapter(onDeviation);
80	    nav.destinationReachedListener = _ArrivalAdapter(onArrival);
81	    nav.routeProgressListener = _ProgressAdapter(onProgress);
82	
83	    nav.route = route;
84	    nav.cameraBehavior = DynamicCameraBehavior();
85	
86	    // Listen for the user grabbing the map so we can release camera ownership.
87	    // We use GestureState.begin — fires once per touch, not every frame.
88	    mapController.gestures.panListener = PanListener(
89	      (gestureState, origin, translation, velocity) {
90	        if (gestureState == GestureState.begin) onPan();
91	      },
92	    );
93	
94	    // Feed every GPS tick to the navigator — distanceFilter:0 so the
95	    // navigator receives every fix, not just every 10 m like the map stream.
96	    _locationSub = Geolocator.getPositionStream(
97	      locationSettings: const LocationSettings(
98	        accuracy: LocationAccuracy.high,
99	        distanceFilter: 0,
100	      ),
101	    ).listen(_forwardLocation);
102	
103	    // Hide global checkpoint markers — only route checkpoints shown during drive.
104	    ref.read(mapControllerProvider.notifier).hideCheckpoints();
105	
106	    // Reset progress so stale data never shows for a new drive.
107	    ref.read(driveProgressProvider.notifier).state = null;
