25	class MapScreen extends ConsumerStatefulWidget {
26	  const MapScreen({super.key});
27	
28	  @override
29	  ConsumerState<MapScreen> createState() => _MapScreenState();
30	}
31	
32	class _MapScreenState extends ConsumerState<MapScreen> {
33	  MapImage? _activeIcon;
34	  MapImage? _inactiveIcon;
35	  MapImage? _policeIcon;
36	  MapImage? _unknownIcon;
37	
38	  List<Checkpoint>? _pendingCheckpoints;
39	
40	  // The first confirmed GPS fix. HereMap is not rendered until this is set.
41	  GeoCoordinates? _initialLocation;
42	
43	  @override
44	  void initState() {
45	    super.initState();
46	    unawaited(_loadIcons());
47	  }
48	
49	  Future<void> _loadIcons() async {
50	    _activeIcon = await _loadImage('assets/images/marker_active.png');
51	    _inactiveIcon = await _loadImage('assets/images/marker_inactive.png');
52	    _policeIcon = await _loadImage('assets/images/marker_police.png');
53	    _unknownIcon = await _loadImage('assets/images/marker_unknown.png');
54	    if (!mounted) return;
55	
56	    final checkpoints =
57	        _pendingCheckpoints ??
58	        ref.read(checkpointNotifierProvider).value?.checkpoints ??
59	        [];
60	    if (checkpoints.isNotEmpty) {
61	      _updateMapCheckpoints(checkpoints);
62	      _pendingCheckpoints = null;
63	    }
64	  }
65	
66	  void _updateMapCheckpoints(List<Checkpoint> checkpoints) {
67	    final active = _activeIcon;
68	    final inactive = _inactiveIcon;
69	    final police = _policeIcon;
70	    final unknown = _unknownIcon;
71	
72	    // Wait for icons AND map controller before rendering.
73	    if (active == null ||
74	        inactive == null ||
75	        police == null ||
76	        unknown == null ||
77	        ref.read(mapControllerProvider) == null) {
78	      _pendingCheckpoints = checkpoints;
79	      return;
80	    }
81	
82	    ref.read(mapControllerProvider.notifier).updateCheckpoints(checkpoints, {
83	      ContributionStatusEnum.ACTIVE: active,
84	      ContributionStatusEnum.INACTIVE: inactive,
85	      ContributionStatusEnum.POLICE_ALERT: police,
86	      ContributionStatusEnum.UNKNOWN: unknown,
87	    });
88	  }
89	
90	  Future<MapImage> _loadImage(String asset) async {
91	    final bytes = await rootBundle.load(asset);
92	    return MapImage.withPixelDataAndImageFormat(
93	      bytes.buffer.asUint8List(),
94	      ImageFormat.png,
95	    );
96	  }
97	
98	  void _onMapCreated(HereMapController hereMapController) {
99	    // Center the map instantly on the known location — no animation, no jump.
100	    final loc = _initialLocation;
101	    if (loc != null) {
102	      hereMapController.camera.lookAtPointWithMeasure(
103	        loc,
104	        MapMeasure(MapMeasureKind.distanceInMeters, 1200),
105	      );
106	    }
107	
108	    ref.read(mapControllerProvider.notifier).setController(
109	      hereMapController,
110	      _onCheckpointTapped,
111	    );
112	
113	    // Pre-warm _lastLocation in the controller so the next GPS update from
114	    // the stream doesn't trigger the fly-to animation again.
115	    if (loc != null) {
116	      ref.read(mapControllerProvider.notifier).setInitialLocation(loc);
117	    }
118	
119	    // Replay any checkpoints that loaded before the map was ready.
120	    // _updateMapCheckpoints stores them in _pendingCheckpoints when the
121	    // controller is null; now that it's set, flush the pending batch.
122	    final pending = _pendingCheckpoints ??
123	        ref.read(checkpointNotifierProvider).value?.checkpoints;
124	    if (pending != null && pending.isNotEmpty) {
125	      _updateMapCheckpoints(pending);
126	    }
127	
128	    hereMapController.camera.addListener(
129	      MapCameraListener((cameraState) {
130	        ref.read(mapBearingProvider.notifier).state =
131	            cameraState.orientationAtTarget.bearing;
132	      }),
133	    );
134	  }
135	
136	  void _onCheckpointTapped(String checkpointId) {
137	    final checkpoints =
138	        ref.read(checkpointNotifierProvider).value?.checkpoints ?? [];
139	    final checkpoint =
140	        checkpoints.where((c) => c.id == checkpointId).firstOrNull;
141	    if (checkpoint != null && context.mounted) {
142	      unawaited(
143	        showModalBottomSheet<void>(
144	          context: context,
145	          isScrollControlled: true,
146	          backgroundColor: Colors.transparent,
147	          builder: (context) => CheckpointActionSheet(checkpoint: checkpoint),
148	        ),
149	      );
150	    }
151	  }
152	
153	  @override
154	  Widget build(BuildContext context) {
155	    // First GPS fix → store initial location and trigger rebuild to show map.
156	    ref
157	      ..listen(userLocationStreamProvider, (_, next) {
158	        final pos = next.value;
159	        if (pos == null) return;
160	        final coords = GeoCoordinates(pos.latitude, pos.longitude);
161	
162	        if (_initialLocation == null) {
163	          setState(() => _initialLocation = coords);
164	        } else {
165	          // Map is rendered; pass updates to the controller directly.
166	          ref.read(mapControllerProvider.notifier).updateLocation(coords);
167	        }
168	      })
169	      ..listen(checkpointNotifierProvider, (_, next) {
170	        next.whenData((data) {
171	          _updateMapCheckpoints(data.checkpoints);
172	        });
173	      });
174	
175	    // Block rendering until we have a confirmed location.
176	    if (_initialLocation == null) {
177	      return const _LocationAcquiringScreen();
178	    }
179	
180	    final phase = ref.watch(navStateNotifierProvider);
181	    final isDriving = phase is ActiveDrive;
182	
183	    return Scaffold(
