185	        builder: (context, constraints) {
186	          // Pixel offset of the sheet's peek edge from the bottom of the body.
187	          // Overlay controls sit just above this line; the sheet slides up
188	          // and covers them when expanded to half or full.
189	          final peekEdge = constraints.maxHeight * kMapSheetMinExtent + 16;
190	
191	          return Stack(
192	            children: [
193	              Listener(
194	                behavior: HitTestBehavior.translucent,
195	                onPointerDown: (_) {
196	                  FocusScope.of(context).unfocus();
197	                  // "Changed my mind": tapping the map while in full search
198	                  // peeks the sheet without discarding typed text.
199	                  if (ref.read(sheetStateNotifierProvider).mode ==
200	                      SheetMode.fullSearch) {
201	                    ref.read(sheetStateNotifierProvider.notifier).peek();
202	                  }
203	                },
204	                child: HereMap(onMapCreated: _onMapCreated),
205	              ),
206	
207	              // Controls anchored just above the peek line.
208	              // Hidden while driving — the nav header takes that role.
209	              if (!isDriving)
210	                Positioned(
211	                  bottom: peekEdge,
212	                  right: 16,
213	                  child: const MapOverlayButtons(),
214	                ),
215	
216	              if (!isDriving)
217	                Positioned(
218	                  bottom: peekEdge,
219	                  left: 16,
220	                  child: const MapSpeedOverlay(),
221	                ),
222	
223	              Positioned(
224	                bottom: peekEdge,
225	                left: 0,
226	                right: 0,
227	                child: const NearbyCheckpointPopup(),
228	              ),
229	
230	              // Recenter button — large, bottom-right, shown only when the
231	              // user has detached the camera during a drive.
232	              if (isDriving && phase.camera == CameraOwnership.free)
233	                Positioned(
234	                  bottom: peekEdge,
235	                  right: 16,
236	                  child: _RecenterButton(
237	                    onTap: () => ref
238	                        .read(navStateNotifierProvider.notifier)
239	                        .recenter(),
240	                  ),
241	                ),
242	
243	              // Top overlay: drive banner while driving, search bar otherwise.
244	              Positioned(
245	                top: 0,
246	                left: 0,
247	                right: 0,
248	                child: isDriving
249	                    ? const DriveBanner()
250	                    : MapSearchBar(
251	                        onCheckpointSelected: (checkpoint) {
252	                          ref
253	                              .read(mapControllerProvider.notifier)
254	                              .focusOnCheckpoint(checkpoint);
255	                        },
256	                      ),
257	              ),
258	
259	              // Sheet is topmost — slides up and covers controls in half/full
260	              // mode; transparent area passes touches through to the map.
261	              const Positioned.fill(child: MapBottomSheet()),
262	            ],
263	          );
264	        },
265	      ),
266	    );
267	  }
268	}
