272	class _RecenterButton extends StatelessWidget {
273	  final VoidCallback onTap;
274	
275	  const _RecenterButton({required this.onTap});
276	
277	  @override
278	  Widget build(BuildContext context) {
279	    return GestureDetector(
280	      onTap: onTap,
281	      child: Container(
