359	                iconColor:   ThemeColors.textTertiary,
360	                hint:        NavStrings.goingToHint,
361	                onChanged:   onDestChanged,
362	                onClear:     onClearDest,
363	              ),
364	            ],
365	          ),
366	
367	          // Swap button: full-height Stack child so GestureDetector
368	          // gets correct hit-test bounds.
369	          Positioned(
370	            right:  ThemeSpacing.sp2,
371	            top:    0,
372	            bottom: 0,
373	            child: Center(
