447	                contentPadding: EdgeInsets.zero,
448	              ),
449	            ),
450	          ),
451	          // 44×44 tap target around a 28dp visual circle — reachable by fat fingers.
452	          if (widget.controller.text.isNotEmpty)
453	            GestureDetector(
454	              onTap: widget.onClear,
